http.Response dashboardPageResponse(http.Request request) {
  final path = request.url.path;
  final body = request.body.isEmpty
      ? <String, dynamic>{}
      : jsonDecode(request.body) as Map<String, dynamic>;
  dynamic data = dashboardPageData[path] ?? <String, dynamic>{};
  if (path == '/api/projects/browse' && '${body['path'] ?? ''}'.endsWith('.md'))
    data = dashboardPageData['/api/projects/browse__file'];
  if (path == '/api/organizations/inspect' && body['job_id'] != null)
    data = {'job_id': body['job_id'], 'streams': []};
  return http.Response(
    jsonEncode(data),
    200,
    headers: {'content-type': 'application/json; charset=utf-8'},
  );
}
